Translate("zhCN", "sentinels", {
	title = "哨兵",
	sections = {
		{
			title = "概述",
			text = [=[哨兵是{link:night-elves}暗夜精灵{/link}的战士。数千年来，她们一直守护着{link:kalimdor}卡利姆多{/link}的森林，并听命于艾露恩的大祭司。她们大多是女性，是既运用女神的恩赐、又挥舞月刃与长弓的女猎手。]=],
		},
		{
			title = "起源",
			text = [=[{link:great-sundering}大分裂{/link}之后，当德鲁伊沉睡于{link:emerald-dream}翡翠梦境{/link}时，艾露恩的女祭司和她们的战士守望着{link:night-elves}卡多雷{/link}。在那漫长的岁月中，哨兵成为了她们人民的盾牌。]=],
		},
		{
			title = "当今",
			text = [=[哨兵们在{link:teldrassil}泰达希尔{/link}的每一座村庄和每一条道路上值守。她们守卫神谕古树，将它的讯息送往{link:darnassus}达纳苏斯{/link}，并与{link:gnarlpine-furbolgs}脊骨熊怪{/link}和{link:harpies}鹰身人{/link}作战。在世界之树之外，她们在{link:darkshore}黑海岸{/link}、{link:ashenvale}灰谷{/link}和{link:feralas}菲拉斯{/link}设有据点。{link:shandris-feathermoon}羽月将军{/link}确保她们每个人都有时间祈祷，而在达纳苏斯，她们监视着城市本身，因为她们担心出了什么不对劲的事。]=],
		},
	},
})
